SELECT id, dept_name, COUNT(budget) OVER w_recent AS running_count_budget, MIN(budget) OVER w_recent AS running_min_budget, AVG(budget) OVER w_recent AS running_avg_budget, ROW_NUMBER() OVER (ORDER BY budget DESC, id ASC) AS seq_no FROM departments WHERE dept_name NOT IN ('Finance', 'Marketing') WINDOW w_recent AS (PARTITION BY dept_name ORDER BY budget ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW);
